package middleware

import (
	"net/http"
	"net/http/httptest"
	"testing"

	"github.com/labstack/echo/v4"
)

type zzTmpNilBalancer struct{}

func (b *zzTmpNilBalancer) AddTarget(*ProxyTarget) bool { return false }
func (b *zzTmpNilBalancer) RemoveTarget(string) bool    { return false }
func (b *zzTmpNilBalancer) Next(echo.Context) *ProxyTarget {
	return nil
}

func zzTmpDo(t *testing.T, b ProxyBalancer) {
	e := echo.New()
	e.Use(Proxy(b))
	e.GET("/", func(c echo.Context) error { return c.String(http.StatusOK, "ok") })

	req := httptest.NewRequest(http.MethodGet, "/", nil)
	rec := httptest.NewRecorder()
	e.ServeHTTP(rec, req)

	if rec.Code != http.StatusServiceUnavailable {
		t.Fatalf("expected status %d, got %d (body=%q)", http.StatusServiceUnavailable, rec.Code, rec.Body.String())
	}
}

func TestZZTmpNoTargets(t *testing.T) {
	t.Run("random balancer with no targets", func(t *testing.T) {
		zzTmpDo(t, NewRandomBalancer(nil))
	})
	t.Run("round robin balancer with no targets", func(t *testing.T) {
		zzTmpDo(t, NewRoundRobinBalancer(nil))
	})
	t.Run("custom balancer returning nil", func(t *testing.T) {
		zzTmpDo(t, &zzTmpNilBalancer{})
	})
}

