func patternMatches(pattern, path string) bool {
	// pattern always starts with '/'
	ps := strings.Split(pattern, "/")
	xs := strings.Split(path, "/")
	anyIdx := -1
	for i, s := range ps {
		if s == "*" {
			anyIdx = i
		}
	}
	if anyIdx >= 0 {
		// '*' matches the remainder of the path (may be empty), but the
		// separator before it must be present.
		if len(xs) < anyIdx+1 {
			return false
		}
		ps = ps[:anyIdx]
		xs = xs[:anyIdx]
	}
	if len(ps) != len(xs) {
		return false
	}
	for i := range ps {
		if strings.HasPrefix(ps[i], ":") {
			if xs[i] == "" {
				return false
			}
			continue
		}
		if ps[i] != xs[i] {
			return false
		}
	}
	return true
}

func randSeg(rnd *rand.Rand) string {
	switch rnd.Intn(5) {
	case 0:
		return "a"
	case 1:
		return "b"
	case 2:
		return "ab"
	case 3:
		return "abc"
	default:
		return "c"
	}
}

func randPattern(rnd *rand.Rand) string {
	n := 1 + rnd.Intn(4)
	segs := make([]string, 0, n)
	for i := 0; i < n; i++ {
		switch rnd.Intn(6) {
		case 0, 1, 2:
			segs = append(segs, randSeg(rnd))
		case 3, 4:
			segs = append(segs, fmt.Sprintf(":p%d", i))
		case 5:
			if i == n-1 {
				segs = append(segs, "*")
			} else {
				segs = append(segs, randSeg(rnd))
			}
		}
	}
	p := "/" + strings.Join(segs, "/")
	if rnd.Intn(6) == 0 {
		p += "/"
	}
	return p
}

func randPath(rnd *rand.Rand) string {
	n := rnd.Intn(5)
	segs := make([]string, 0, n)
	for i := 0; i < n; i++ {
		segs = append(segs, randSeg(rnd))
	}
	p := "/" + strings.Join(segs, "/")
	if n > 0 && rnd.Intn(4) == 0 {
		p += "/"
	}
	return p
}

