		{"xfprotocol http", map[string]string{HeaderXForwardedProtocol: "http"}, false, "http"},
		{"xfssl on", map[string]string{HeaderXForwardedSsl: "on"}, false, "https"},
		{"xurlscheme https", map[string]string{HeaderXUrlScheme: "https"}, false, "https"},
		{"no headers", map[string]string{}, false, "http"},
		{"tls", map[string]string{}, true, "https"},
	}
