// Mimics the likely hidden test: TestDefaultBinder_bindDataToMap
func TestDefaultBinder_bindDataToMap(t *testing.T) {
	type args struct {
		destination interface{}
		data        map[string][]string
	}
	tests := []struct {
		name    string
		args    args
		want    interface{}
		wantErr bool
	}{
		{
			name: "ok, bind to map[string][]string",
			args: args{
				destination: &map[string][]string{},
				data:        map[string][]string{"a": {"1", "2"}, "b": {"3"}},
			},
			want: map[string][]string{"a": {"1", "2"}, "b": {"3"}},
		},
		{
			name: "ok, bind to map[string]string",
			args: args{
				destination: &map[string]string{},
				data:        map[string][]string{"a": {"1", "2"}, "b": {"3"}},
			},
			want: map[string]string{"a": "1", "b": "3"},
		},
		{
			name: "ok, bind to map[string]interface{}",
			args: args{
				destination: &map[string]interface{}{},
				data:        map[string][]string{"a": {"1"}, "b": {"2"}},
			},
			want: map[string]interface{}{"a": "1", "b": "2"},
		},
		{
			name: "nok, unsupported map value type",
			args: args{
				destination: &map[string]int{},
				data:        map[string][]string{"a": {"1"}},
			},
			wantErr: true,
		},
		{
			name: "nok, unsupported map key type",
			args: args{
				destination: &map[int]string{},
				data:        map[string][]string{"a": {"1"}},
			},
			wantErr: true,
		},
		{
			name: "nok, unsupported slice element type",
			args: args{
				destination: &map[string][]int{},
				data:        map[string][]string{"a": {"1"}},
			},
			wantErr: true,
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			b := &DefaultBinder{}
			err := b.bindDataToMap(tt.args.destination, tt.args.data)
			if tt.wantErr {
				assert.Error(t, err)
				return
			}
			assert.NoError(t, err)
			switch d := tt.args.destination.(type) {
			case *map[string][]string:
				assert.Equal(t, tt.want, *d)
			case *map[string]string:
				assert.Equal(t, tt.want, *d)
			case *map[string]interface{}:
				assert.Equal(t, tt.want, *d)
			default:
				t.Fatalf("unexpected destination type %T", tt.args.destination)
			}
		})
	}
}

