func dump(t *testing.T, name string, rec *httptest.ResponseRecorder) {
	b := rec.Body.Bytes()
	fmt.Printf("=== %s\n  status=%d\n  Content-Encoding=%q\n  Content-Length=%q\n  Content-Type=%q\n  bodylen=%d bodyhex=%s\n",
