	r, err := gzip.NewReader(bytes.NewReader(b))
	if err != nil {
		fmt.Printf("  gzip.NewReader err=%v\n", err)
		return
	}
	out, err := ioutil.ReadAll(r)
	fmt.Printf("  gzip decompressed=%q err=%v\n", string(out), err)
